java.util.Calendar calendar = java.util.Calendar.getInstance();
ClipboardPage PageRespondStatus_p = tools.findPage("TempsNext");
int day_ = PRNumberFormat.parseLocalizedAsInteger(null, PageRespondStatus_p.getProperty(".Country").toString());
int months_ = PRNumberFormat.parseLocalizedAsInteger(null, myStepPage.getString(".CountryID"));
int years_ = PRNumberFormat.parseLocalizedAsInteger(null, myStepPage.getString(".City"));
int nextdays = PRNumberFormat.parseLocalizedAsInteger(null, myStepPage.getString(".CityID"));
calendar.set(day_, months_, years_);
int days = calendar.getActualMaximum(java.util.Calendar.DAY_OF_MONTH);
String new_day="";
String new_month="";
String new_year=String.valueOf(years_);
if(day_+nextdays>days){
  if(day_+nextdays-days <10){
    new_day = "0"+String.valueOf(day_+nextdays-days);
  }else{
    new_day = String.valueOf(day_+nextdays-days);
  }
  months_ +=1;
}
if(day_+nextdays<=days){
  if(day_+nextdays<=9){
    new_day = "0"+String.valueOf(day_+nextdays);
  }else{
    new_day = String.valueOf(day_+nextdays);
  }
}
if(months_>12)
{
  new_month="01";
  new_year = String.valueOf(years_+1);
}
if(months_<=12)
{
  if(months_<10)
  {
    new_month="0"+String.valueOf(months_);
  }
  else{
    new_month=String.valueOf(months_);
  }

}

String hasils = new_day+"/"+new_month+"/"+new_year;
PageRespondStatus_p.getProperty(".AnalystTransferDate").setValue(hasils);
